export default "/* mail.css — domain residue for com.ikenga.mail.\n *\n * Only mail-local classes live here (.mail-row*, .reader-*, .thread-*, .pane-split).\n * Kit primitives (.frame*, .ip-*, .dense-row*, .btn*, .tag, .chip, .badge,\n * .atelier-state*, .avatar*, .chat-msg*, .nav-group*, .nav-item*, etc.) are\n * consumed from app-kit-css.js — never re-derived here.\n *\n * Inject order: tokens-css → app-kit-css → mail-css (this file).\n * Scoped under data-workspace=\"mail\" where needed (amber tint).\n */\n\n/* ── Reduced motion gate ── */\n@media (prefers-reduced-motion: reduce) {\n  .mail-row { transition: none; }\n}\n\n/* ── Root frame ── */\n.frame {\n  height: 100%;\n}\n\n/* ── Two-column split ── */\n/* mail-local — NOT .ip-split (the reading pane is richer than a pipeline detail) */\n.pane-split {\n  display: grid;\n  grid-template-columns: 380px 1fr;\n  overflow: hidden;\n  height: 100%;\n}\n\n/* ── Mail list column ── */\n.mail-list {\n  display: flex;\n  flex-direction: column;\n  overflow: hidden;\n  /* grid item in .pane-split: min-height:auto would block the inner\n     .mail-list-scroll (flex:1; overflow-y:auto) from shrinking → no scroll. */\n  min-height: 0;\n  background: var(--bg-surface, var(--bg-base));\n  border-right: 1px solid var(--border-soft, rgba(0,0,0,0.08));\n}\n\n.mail-list-head {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: var(--space-2);\n  padding: var(--space-3) var(--space-4);\n  border-bottom: 1px solid var(--border-soft, rgba(0,0,0,0.06));\n  flex-shrink: 0;\n}\n\n.mail-list-head-title {\n  font-family: var(--font-display);\n  font-weight: 500;\n  font-size: var(--text-h3, 1.05rem);\n  color: var(--fg);\n  line-height: 1.3;\n}\n\n.mail-list-head-meta {\n  font-family: var(--font-mono, monospace);\n  font-size: 10.5px;\n  letter-spacing: 0.04em;\n  color: var(--fg-faint, var(--fg-muted));\n  white-space: nowrap;\n}\n\n.mail-list-search {\n  padding: 8px 10px 6px;\n  flex-shrink: 0;\n}\n\n.mail-list-search-row {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  background: var(--bg-sunken, var(--bg-raised));\n  border: 1px solid var(--border-soft, rgba(0,0,0,0.08));\n  border-radius: 6px;\n  padding: 0 8px;\n  height: 30px;\n  color: var(--fg-muted);\n}\n\n.mail-list-search-row .input {\n  flex: 1;\n  border: none;\n  background: transparent;\n  font-size: 0.8rem;\n  color: var(--fg);\n  outline: none;\n  padding: 0;\n}\n\n.mail-list-search-row .input::placeholder {\n  color: var(--fg-faint, var(--fg-muted));\n  font-style: italic;\n}\n\n.mail-list-section {\n  padding: var(--space-3) var(--space-4) var(--space-1);\n  font-family: var(--font-mono, monospace);\n  font-size: 10px;\n  font-weight: 500;\n  text-transform: uppercase;\n  letter-spacing: 0.12em;\n  color: var(--fg-faint, var(--fg-muted));\n  background: var(--bg-sunken, var(--bg-base));\n  border-bottom: 1px solid var(--border-soft, rgba(0,0,0,0.06));\n  flex-shrink: 0;\n}\n\n/* Scrollable thread list area — wraps the date-grouped sections. */\n.mail-list-scroll {\n  overflow-y: auto;\n  flex: 1;\n  min-height: 0;\n}\n\n/* ── Mail row ── */\n/* Design (atelier-mail.html): two-column grid — 4px tick + 1fr body. */\n.mail-row {\n  display: grid;\n  grid-template-columns: 4px 1fr;\n  gap: var(--space-2);\n  align-items: stretch;\n  cursor: pointer;\n  padding: calc(var(--row-pad-y) + 4px) var(--space-4);\n  border-bottom: 1px solid var(--border-soft, rgba(0,0,0,0.06));\n  transition: background var(--motion-fast, 120ms) var(--ease-calm, ease);\n  outline: none;\n}\n\n.mail-row:hover,\n.mail-row.is-selected {\n  background: var(--bg-raised);\n}\n\n.mail-row:focus-visible {\n  outline: 2px solid var(--primary);\n  outline-offset: -2px;\n}\n\n/* Left accent stripe — fills with the workspace tint when unread or selected */\n.mail-row-tick {\n  width: 4px;\n  border-radius: 2px;\n  background: transparent;\n  transition: background var(--motion-fast, 120ms) var(--ease-calm, ease);\n}\n\n.mail-row.is-unread .mail-row-tick,\n.mail-row.is-selected .mail-row-tick {\n  background: var(--tint-fg-active, var(--tint-mail-fg, hsl(42,70%,62%)));\n}\n\n.mail-row-body {\n  min-width: 0;\n}\n\n.mail-row-meta {\n  display: flex;\n  justify-content: space-between;\n  align-items: baseline;\n  gap: 6px;\n  margin-bottom: 2px;\n}\n\n.mail-row-from {\n  font-size: var(--text-body-sm, 0.82rem);\n  font-weight: 500;\n  color: var(--fg);\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  flex: 1;\n}\n\n.mail-row.is-unread .mail-row-from {\n  font-weight: 600;\n}\n\n.mail-row-time {\n  font-family: var(--font-mono, monospace);\n  font-size: 10.5px;\n  color: var(--fg-faint, var(--fg-muted));\n  white-space: nowrap;\n  flex-shrink: 0;\n}\n\n/* Subject is full --fg in the design for read + unread; weight carries unread. */\n.mail-row-subject {\n  font-size: var(--text-body-sm, 0.82rem);\n  color: var(--fg);\n  line-height: 1.35;\n  margin-bottom: 3px;\n  overflow: hidden;\n  display: -webkit-box;\n  -webkit-line-clamp: 1;\n  -webkit-box-orient: vertical;\n}\n\n.mail-row.is-unread .mail-row-subject {\n  font-weight: 500;\n}\n\n/* Two-line preview clamp (design: -webkit-line-clamp: 2). */\n.mail-row-preview {\n  font-size: var(--text-caption, 0.78rem);\n  color: var(--fg-muted);\n  line-height: 1.4;\n  overflow: hidden;\n  display: -webkit-box;\n  -webkit-line-clamp: 2;\n  -webkit-box-orient: vertical;\n}\n\n.mail-row-tags {\n  display: flex;\n  gap: var(--space-1);\n  flex-wrap: wrap;\n  margin-top: var(--space-2);\n}\n\n/* ── Reader pane ── */\n.reader-pane {\n  display: flex;\n  flex-direction: column;\n  overflow: hidden;\n  height: 100%;\n  background: var(--bg-base);\n}\n\n.reader-toolbar {\n  display: flex;\n  align-items: center;\n  gap: 2px;\n  padding: 6px 10px;\n  border-bottom: 1px solid var(--border-soft, rgba(0,0,0,0.06));\n  flex-shrink: 0;\n  background: var(--bg-surface, var(--bg-base));\n}\n\n.reader-toolbar-spacer {\n  flex: 1;\n}\n\n.reader-toolbar-meta {\n  font-size: 0.72rem;\n  color: var(--fg-faint, var(--fg-muted));\n  font-variant-numeric: tabular-nums;\n}\n\n.reader-body-wrap {\n  flex: 1;\n  overflow-y: auto;\n  min-height: 0;\n  padding: var(--space-6) var(--space-8);\n  max-width: 780px;\n  margin: 0 auto;\n  width: 100%;\n  display: flex;\n  flex-direction: column;\n  gap: var(--space-5);\n}\n\n.reader-head {\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n}\n\n.reader-from-row {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n}\n\n.reader-from-name {\n  font-size: 0.88rem;\n  font-weight: 600;\n  color: var(--fg);\n  line-height: 1.25;\n}\n\n.reader-from-addr {\n  font-size: 0.76rem;\n  color: var(--fg-muted);\n  line-height: 1.3;\n}\n\n.reader-actions {\n  display: flex;\n  gap: 6px;\n  margin-left: auto;\n  flex-shrink: 0;\n}\n\n/* Display heading — Fraunces 30px / 500, per design. */\n.reader-subject {\n  font-family: var(--font-display);\n  font-weight: 500;\n  font-size: 30px;\n  line-height: 1.15;\n  letter-spacing: -0.012em;\n  color: var(--fg);\n  margin-bottom: var(--space-3);\n}\n\n/* Mono dot-separated meta chips — separators inserted via ::before (design). */\n.reader-meta {\n  font-family: var(--font-mono, monospace);\n  font-size: 10.5px;\n  letter-spacing: 0.04em;\n  color: var(--fg-muted);\n  display: flex;\n  gap: var(--space-4);\n  align-items: center;\n  flex-wrap: wrap;\n}\n\n.reader-meta span::before {\n  content: '· ';\n  color: var(--fg-faint);\n  margin-right: 2px;\n}\n\n.reader-meta span:first-child::before {\n  content: '';\n  margin: 0;\n}\n\n.reader-meta .reader-meta-deal {\n  color: var(--achievement);\n}\n\n.reader-body {\n  font-size: var(--text-body, 0.875rem);\n  line-height: 1.7;\n  color: var(--fg);\n  font-family: var(--font-body);\n  max-width: 64ch;\n}\n\n.reader-body p {\n  margin: 0 0 var(--space-4);\n}\n\n.reader-body strong {\n  color: var(--achievement);\n  font-weight: 600;\n}\n\n/* ── Quick reply ── */\n.reader-quick-reply {\n  border: 1px solid var(--border-soft, rgba(0,0,0,0.1));\n  border-radius: 8px;\n  overflow: hidden;\n  background: var(--bg-raised);\n}\n\n.reader-quick-reply-head {\n  padding: 8px 12px;\n  border-bottom: 1px solid var(--border-soft, rgba(0,0,0,0.06));\n  background: var(--bg-surface, var(--bg-base));\n}\n\n/* Amber label — drafted-by-Chi affordance (design uses --achievement). */\n.reader-quick-reply-tag {\n  font-family: var(--font-mono, monospace);\n  font-size: 10px;\n  letter-spacing: 0.08em;\n  text-transform: uppercase;\n  color: var(--achievement);\n}\n\n.reader-quick-reply .input {\n  display: block;\n  width: 100%;\n  border: none;\n  border-radius: 0;\n  background: transparent;\n  padding: 10px 12px;\n  font-size: var(--text-body, 0.85rem);\n  font-family: var(--font-body);\n  color: var(--fg);\n  line-height: 1.6;\n  resize: vertical;\n  min-height: 64px;\n  outline: none;\n}\n\n.reader-quick-reply-foot {\n  display: flex;\n  align-items: center;\n  padding: var(--space-2) 12px var(--space-2) 12px;\n  margin-top: 0;\n  border-top: 1px solid var(--border-soft, rgba(0,0,0,0.06));\n  font-family: var(--font-mono, monospace);\n  font-size: 10px;\n  letter-spacing: 0.04em;\n  color: var(--fg-faint, var(--fg-muted));\n  gap: var(--space-2);\n  flex-wrap: wrap;\n}\n\n.reader-quick-reply-foot kbd {\n  font-family: var(--font-mono, monospace);\n  font-size: 10px;\n  color: var(--fg-faint, var(--fg-muted));\n  background: var(--bg-base);\n  border: 1px solid var(--border-soft, rgba(0,0,0,0.08));\n  border-radius: var(--radius-xs, 3px);\n  padding: 1px 5px;\n  margin-right: 1px;\n}\n\n/* Tone hint sits at the right edge, amber, when a draft is present. */\n.reader-quick-reply-tone {\n  margin-left: auto;\n  color: var(--achievement);\n}\n\n/* No-draft state pushes the shortcut hints to the right edge. */\n.reader-quick-reply-foot-spacer {\n  flex: 1;\n}\n\n/* ── Thread collapse rail ── */\n.thread-other {\n  margin: 8px 0;\n}\n\n.thread-collapse {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  cursor: pointer;\n  background: none;\n  border: none;\n  padding: 4px 0;\n  font-size: 0.78rem;\n  color: var(--fg-muted);\n  width: 100%;\n  text-align: left;\n}\n\n.thread-collapse-line {\n  flex: 1;\n  height: 1px;\n  background: var(--border-soft, rgba(0,0,0,0.08));\n}\n\n/* ── Workspace amber tint (applied when data-workspace=\"mail\") ── */\n/* The shell already sets --tint-mail-bg / --tint-mail-fg via @ikenga/tokens;\n * we just document the mapping here for reference.\n *   dark:  --tint-mail-bg = hsl(42,30%,11%); --tint-mail-fg = hsl(42,70%,62%)\n *   light: --tint-mail-bg = hsl(42,60%,92%); --tint-mail-fg = hsl(42,80%,28%)\n */\n[data-workspace=\"mail\"] {\n  --tint-bg-active: var(--tint-mail-bg, hsl(42, 30%, 11%));\n  --tint-fg-active: var(--tint-mail-fg, hsl(42, 70%, 62%));\n}\n\n/* Mail tag colours are owned by the app-kit (.tag-deal/.tag-warn/.tag-system/\n * .tag-primary all reference @ikenga/tokens). No mail-local override needed —\n * the previous overrides used a non-token `--amber` and silently fell back. */\n\n/* ─── Tier-B proposals ──────────────────────────────────────────────────────\n   Approval surface for email_actions rows at status='proposed'. Built on the\n   existing token set only (no new custom properties) so the planned mail-app\n   revamp can restyle it without unpicking a private palette. */\n\n.proposal-wrap {\n  display: flex;\n  flex-direction: column;\n  min-height: 0;\n  flex: 1;\n}\n\n/* Header is fixed furniture — never let it absorb the shrink. */\n.proposal-wrap > .mail-list-head { flex-shrink: 0; }\n\n/* Owns the scroll axis. `flex: 1` is load-bearing: without it this box is\n   flex: 0 1 auto inside .proposal-wrap, so it never claims the free space and\n   instead SHRINKS — squashing the cards rather than scrolling them. */\n.proposal-scroll {\n  overflow-y: auto;\n  padding: var(--space-3);\n  display: flex;\n  flex-direction: column;\n  gap: var(--space-2);\n  flex: 1;\n  min-height: 0;\n}\n\n/* `flex-shrink: 0` is the fix for clipped rows. As a flex item in a column\n   container, a card defaults to flex-shrink:1 — when the pane is shorter than\n   the list, every card gets compressed below its content height and the text\n   clips, instead of the container scrolling. Shrinking must be off for the\n   overflow on .proposal-scroll to engage at all. */\n.proposal-card {\n  border: 1px solid var(--border-soft);\n  border-radius: var(--radius-md);\n  background: var(--bg-surface);\n  overflow: hidden;\n  flex-shrink: 0;\n}\n\n.proposal-head {\n  display: flex;\n  align-items: center;\n  gap: var(--space-3);\n  padding: var(--space-3);\n  cursor: pointer;\n  flex-wrap: wrap;\n}\n\n.proposal-head:hover { background: var(--bg-sunken); }\n.proposal-head:focus-visible { outline: 2px solid var(--color-ring-primary); outline-offset: -2px; }\n\n/* Tabular numerals keep the count column aligned down a long list. */\n.proposal-n {\n  font-family: var(--font-mono);\n  font-variant-numeric: tabular-nums;\n  font-weight: 700;\n  min-width: 3.5ch;\n  text-align: right;\n}\n\n.proposal-cluster { font-weight: 600; flex: 1; min-width: 12rem; }\n.proposal-arrow { color: var(--fg-muted); font-size: 0.8125rem; }\n\n.proposal-body {\n  padding: 0 var(--space-3) var(--space-3);\n  border-top: 1px solid var(--border-soft);\n}\n\n.proposal-ev {\n  display: flex;\n  gap: var(--space-4);\n  flex-wrap: wrap;\n  margin: var(--space-3) 0;\n  font-size: 0.8125rem;\n}\n.proposal-ev div { color: var(--fg-muted); }\n.proposal-ev b {\n  color: var(--fg);\n  font-family: var(--font-mono);\n}\n\n/* Held-back notice. Deliberately high-contrast: it is the one piece of context\n   that changes what approving actually does. */\n.proposal-hold {\n  display: flex;\n  align-items: flex-start;\n  gap: var(--space-2);\n  padding: var(--space-2) var(--space-3);\n  border-radius: var(--radius-sm);\n  background: var(--color-background-warning));\n  color: var(--color-text-warning);\n  font-size: 0.8125rem;\n  margin-bottom: var(--space-2);\n}\n\n.proposal-samples {\n  margin: var(--space-2) 0 0;\n  padding-left: 1.125rem;\n  color: var(--fg-muted);\n  font-size: 0.8125rem;\n}\n\n.proposal-details { margin-top: var(--space-3); font-size: 0.8125rem; }\n.proposal-details summary { cursor: pointer; color: var(--fg-muted); }\n\n.proposal-msg-scroll {\n  max-height: 16rem;\n  overflow-y: auto;\n  margin-top: var(--space-2);\n  border: 1px solid var(--border-soft);\n  border-radius: var(--radius-sm);\n}\n\n.proposal-msg {\n  display: flex;\n  gap: var(--space-3);\n  align-items: baseline;\n  padding: 5px var(--space-2);\n  border-bottom: 1px solid var(--border-soft);\n}\n.proposal-msg:last-child { border-bottom: 0; }\n\n.proposal-msg-uid {\n  font-family: var(--font-mono);\n  color: var(--fg-muted);\n  white-space: nowrap;\n}\n.proposal-msg-subject {\n  flex: 1;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.proposal-actions {\n  display: flex;\n  align-items: center;\n  gap: var(--space-2);\n  margin-top: var(--space-3);\n  flex-wrap: wrap;\n}\n.proposal-actions-note {\n  color: var(--fg-muted);\n  font-size: 0.75rem;\n  flex: 1;\n  min-width: 14rem;\n}\n\n.proposal-queued {\n  display: flex;\n  align-items: center;\n  gap: var(--space-2);\n  padding: var(--space-2) var(--space-3);\n  border-radius: var(--radius-sm);\n  background: var(--bg-sunken);\n  color: var(--fg-muted);\n  font-size: 0.8125rem;\n}\n\n.proposal-decided { padding: 0 var(--space-1); }\n"
